        self.shifts: list[Shift] = []

    def rested(self, aid: str, segs, min_rest: float) -> bool:
        """Rest against the agent's shifts on other days (before and after this one)."""
        start, end = segs[0][0], segs[-1][1]
        gap = timedelta(hours=min_rest)
        for d in self.days[aid]:
            sh = self.by_day[(aid, d)]
