enforce (`scheduler: week` in the client config). Used for Northwind (docs/NORTHWIND_SOW.md §2).

Differences from `greedy.py`, all enforced while placing rather than audited afterwards:
  - rest: at least `min_rest_hours` elapsed between the end of one shift and the start of the next;
  - split templates only for the contracts in `split_shift_contracts`;
  - weekly hours are the elapsed hours of the segments (UTC), not the template's nominal hours;
  - minimum cover (`min_cover`) is held net of breaks; only agents on the queue count;
  - breaks (`break.placement: max_surplus`): in the window, the planning interval where the queue's gross
    coverage surplus (agents on the queue ignoring breaks, minus required) is largest. Among tied
    intervals the one with most room left (gross minus what the interval needs, minus breaks already
    there) is used, so breaks do not take net cover below the requirement;
  - coverage is checked net of breaks: where breaks still leave an interval short, the shortfall is
    added to that interval's target and placement resumes, until nothing more can be fixed.

Deterministic: fixed template order, agent ids as the final tie-break.
"""
from __future__ import annotations

from collections import defaultdict
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

import pandas as pd

from wfm import constraints
from wfm.ingest.loader import local_days
from wfm.roster import Agent
from wfm.scheduler.greedy import Shift, _covered, _would_exceed_run
from wfm.scheduler.templates import Template, templates_for

MAX_ROUNDS = 12
SCORE = lambda val, n: (val, val / n)


def split_allowed(tpl: Template, contract: str, cfg: dict) -> bool:
    allowed = cfg.get("split_shift_contracts")
    return not tpl.is_split or allowed is None or contract in allowed


def _elapsed_hours(segs) -> float:
    return sum((e - s).total_seconds() for s, e in segs) / 3600.0


class _State:
    def __init__(self, agents: list[Agent]):
        self.hours: dict[str, float] = defaultdict(float)
        self.days: dict[str, list[date]] = defaultdict(list)
        self.by_day: dict[tuple[str, date], Shift] = {}
        self.shifts: list[Shift] = []

    def rested(self, aid: str, segs, min_rest: float) -> bool:
        """Rest against the agent's shifts on other days (before and after this one)."""
        start, end = segs[0][0], segs[-1][1]
        gap = timedelta(hours=min_rest)
        for d in self.days[aid]:
            sh = self.by_day[(aid, d)]
            s0, e0 = sh.segments[0][0], sh.segments[-1][1]
            if e0 <= start and start - e0 < gap:
                return False
            if end <= s0 and s0 - end < gap:
                return False
            if s0 < end and start < e0:
                return False
        return True

    def run_ok(self, aid: str, day: date, max_run: int) -> bool:
        days = sorted(set(self.days[aid]) | {day})
        run = best = 1
        for d1, d2 in zip(days, days[1:]):
            run = run + 1 if (d2 - d1).days == 1 else 1
            best = max(best, run)
        return best <= max_run


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    tz = cfg["tz"]
    z = ZoneInfo(tz)
    caps = cfg["weekly_hours"]
    max_run = cfg["max_consecutive_days"]
    min_rest = float(cfg.get("min_rest_hours") or 0)
    templates = templates_for(cfg)
    queues = list(dict.fromkeys(req["queue"]))
    grid = sorted(set(req["interval_start_utc"]))
    required = {q: defaultdict(int, zip(g["interval_start_utc"], g["required"])) for q, g in req.groupby("queue")}
    floors = {q: {t: constraints.floor(q, t, cfg) for t in grid} for q in queues}
    need = {q: {t: max(required[q][t], floors[q][t]) for t in grid} for q in queues}
    extra = {q: defaultdict(int) for q in queues}
    days = local_days(week, tz)
    day_grid = {d: [t for t in grid if t.astimezone(z).date() == d] for d in days}
    # agents holding a skill few others hold are kept for that queue where possible
    holders = {q: sum(q in a.skills for a in agents) for q in queues}
    scarce = {q for q in queues if holders[q] and holders[q] <= len(agents) / 4}

    st = _State(agents)
    gross = {q: defaultdict(int) for q in queues}

    tpl_segs = {(tpl.id, d): tpl.segments_utc(d, tz) for tpl in templates for d in days}
    tpl_ivs = {k: _covered(v, day_grid[k[1]]) for k, v in tpl_segs.items()}

    def place(on_days: list[date]) -> bool:
        """Global greedy over the given days: repeatedly place the (day, template, queue) that covers
        the most uncovered target (ties: the higher share of its intervals), on the best agent."""
        placed_any = False
        dead: set[tuple[str, str, date]] = set()
        while True:
            best, best_key = None, None
            for day in on_days:
                for tpl in templates:
                    ivs = tpl_ivs[(tpl.id, day)]
                    if not ivs:
                        continue
                    for q in queues:
                        if (tpl.id, q, day) in dead:
                            continue
                        val = sum(min(1, max(0, need[q][t] + extra[q][t] - gross[q][t])) for t in ivs)
                        if val < 1 - 1e-9:   # at least one interval of uncovered target
                            continue
                        key = SCORE(val, len(ivs))
                        if best_key is None or key > best_key:
                            best, best_key = (tpl, q, day), key
            if best is None:
                return placed_any
            tpl, q, day = best
            segs, ivs = tpl_segs[(tpl.id, day)], tpl_ivs[(tpl.id, day)]
            h = _elapsed_hours(segs)
            cands = [a for a in agents
                     if q in a.skills and (a.agent_id, day) not in st.by_day
                     and split_allowed(tpl, a.contract, cfg)
                     and st.hours[a.agent_id] + h <= caps[a.contract] + 1e-9
                     and st.run_ok(a.agent_id, day, max_run)
                     and st.rested(a.agent_id, segs, min_rest)]
            if not cands:
                dead.add((tpl.id, q, day))
                continue
            a = min(cands, key=lambda x: (bool((x.skills & scarce) - {q}), st.hours[x.agent_id], x.agent_id))
            sh = Shift(a.agent_id, q, tpl, day, segs, ivs)
            st.shifts.append(sh)
            st.by_day[(a.agent_id, day)] = sh
            st.days[a.agent_id].append(day)
            st.hours[a.agent_id] += h
            for t in ivs:
                gross[q][t] += 1
            placed_any = True

    place(days)
    for _ in range(MAX_ROUNDS):
        place_breaks(st.shifts, cfg, required, need, grid)
        short = _net_short(st.shifts, cfg, need, grid, queues)
        if not short:
            break
        for q, t in short:
            extra[q][t] += 1
        if not place(days):
            break
    place_breaks(st.shifts, cfg, required, need, grid)
    return st.shifts


def _gross(shifts: list[Shift]) -> dict:
    g = defaultdict(lambda: defaultdict(int))
    for sh in shifts:
        for t in sh.intervals:
            g[sh.queue][t] += 1
    return g


def _net_short(shifts, cfg, need, grid, queues) -> list[tuple[str, datetime]]:
    g = _gross(shifts)
    brk = defaultdict(lambda: defaultdict(int))
    for sh in shifts:
        if sh.break_start is not None:
            brk[sh.queue][sh.break_start] += 1
    return [(q, t) for q in queues for t in grid if g[q][t] - brk[q][t] < need[q][t]]


def break_candidates(sh: Shift, cfg: dict, step: timedelta) -> list[datetime]:
    """Planning intervals where the shift's break may start: between window_hours after the shift
    start (both ends included) and inside a segment with room for the whole break."""
    rule = cfg["break"]
    lo, hi = rule["window_hours"]
    length = timedelta(minutes=rule["minutes"])
    start = sh.segments[0][0]
    return [t for t in sh.intervals
            if start + timedelta(hours=lo) <= t <= start + timedelta(hours=hi)
            and any(s <= t and t + length <= e for s, e in sh.segments)]


def place_breaks(shifts: list[Shift], cfg: dict, required: dict, need: dict, grid) -> None:
    """SOW-style breaks: the interval of largest gross surplus in the window; ties by room left."""
    rule = cfg["break"]
    step = timedelta(minutes=cfg["interval_minutes"])
    gross = _gross(shifts)
    surplus = lambda q, t: gross[q][t] - required[q].get(t, 0)
    room = defaultdict(lambda: defaultdict(int))
    for sh in shifts:
        sh.break_start, sh.break_minutes = None, 0
    long = [sh for sh in shifts if sh.hours >= rule["min_shift_hours"] - 1e-9]
    tied = {}
    for sh in long:
        cands = break_candidates(sh, cfg, step)
        if not cands:
            continue
        top = max(surplus(sh.queue, t) for t in cands)
        tied[id(sh)] = [t for t in cands if surplus(sh.queue, t) == top]
    for q in {sh.queue for sh in long}:
        for t in grid:
            room[q][t] = gross[q][t] - need[q].get(t, 0)
    order = sorted((sh for sh in long if id(sh) in tied),
                   key=lambda s: (len(tied[id(s)]), s.segments[0][0], s.agent_id))
    for sh in order:
        ts = tied[id(sh)]
        hi_edge = sh.segments[0][0] + timedelta(hours=rule["window_hours"][1])
        # most room first; prefer not to sit on the window's closing edge; then earliest
        t = max(ts, key=lambda t: (room[sh.queue][t], t != hi_edge, -t.timestamp()))
        sh.break_start = t
        sh.break_minutes = rule["minutes"]
