        """Days with a floor gap or an edge-only break on queue q."""
        brk, _ = self.breaks(q)
        net = list(self.gross[q])
        for i in brk.values():
            net[i] -= 1
        days = {self.grid[i].astimezone(self.z).date() for i, (f, x) in enumerate(zip(self.floor[q], net)) if x < f}
        gross, req = self.gross[q], self.required[q]
        for (aid, day), (tid, qq) in self.plan.items():
            _, _, ix, h, cands, edge = self.shape[(tid, day)]
            if qq == q and h >= self.long_h - 1e-9 and cands:
                top = max(gross[i] - req[i] for i in cands)
                if [i for i in cands if gross[i] - req[i] == top] == [edge]:
                    days.add(day)
        return sorted(days)

    def repair(self, q: str, rounds: int = 6) -> None:
        """Pair moves on the days that still break a rule: change two agent-days of the day together."""
        for _ in range(rounds):
            cur = self.cost(q)
            if cur[0] == 0:
                return
            improved = False
            for day in self.defect_days(q):
                slots = [a.agent_id for a in self.holders(q)
                         if not (self.plan.get((a.agent_id, day)) and self.plan[(a.agent_id, day)][1] != q)]
                opts = [None] + [(t.id, q) for t in self.templates]
                best, best_cost = None, cur
                for x, y in itertools.combinations(slots, 2):
                    hx, hy = self.plan.get((x, day)), self.plan.get((y, day))
                    for ox in opts:
                        if ox != hx and ox and not self.can_take(x, day, ox[0], q):
                            continue
                        self.set(x, day, ox)
                        for oy in opts:
                            if (ox, oy) == (hx, hy) or (oy != hy and oy and not self.can_take(y, day, oy[0], q)):
                                continue
                            self.set(y, day, oy)
                            if self.total_hours <= self.hours_budget + 1e-9:
                                c = self.cost(q)
                                if c < best_cost:
                                    best, best_cost = (ox, oy), c
                            self.set(y, day, hy)
                        self.set(x, day, hx)
                    if best and best_cost[0] < cur[0]:
                        break
                if best:
                    self.set(x if False else x, day, self.plan.get((x, day)))
                    bx, by = best
                    # re-find which pair produced best: apply by search below
                    pass
                if best:
                    improved = self._apply_best_pair(q, day, slots, opts, best_cost) or improved
                    cur = self.cost(q)
            if not improved:
                return

    def _apply_best_pair(self, q, day, slots, opts, target) -> bool:
        for x, y in itertools.combinations(slots, 2):
            hx, hy = self.plan.get((x, day)), self.plan.get((y, day))
            for ox in opts:
                if ox != hx and ox and not self.can_take(x, day, ox[0], q):
                    continue
                self.set(x, day, ox)
                for oy in opts:
                    if (ox, oy) == (hx, hy) or (oy != hy and oy and not self.can_take(y, day, oy[0], q)):
                        continue
                    self.set(y, day, oy)
                    if self.total_hours <= self.hours_budget + 1e-9 and self.cost(q) == target:
                        return True
                    self.set(y, day, hy)
                self.set(x, day, hx)
        return False

    def shifts(self) -> list[Shift]:''')
