p="wfm/evaluate/metrics.py"; s=open(p).read()
s=s.replace('''    sla, under, over = {}, 0.0, 0.0
    for q, g in req.groupby("queue"):
        met = tot = 0
        for r in g.itertuples(index=False):
            if r.volume <= 0:
                continue''','''    # `attainment_intervals: operating` (Northwind SOW 1.6): every interval inside the queue's operating
    # hours (`queue_hours`, else `operating_hours`) counts; the default counts intervals with volume.
    z = ZoneInfo(cfg["tz"])
    operating = cfg.get("attainment_intervals") == "operating"
    qhours = cfg.get("queue_hours") or {}

    def counted(q, r) -> bool:
        if not operating:
            return r.volume > 0
        lo, hi = qhours.get(q, cfg["operating_hours"])
        loc = r.interval_start_utc.astimezone(z)
        return lo <= loc.hour + loc.minute / 60 < hi

    sla, under, over = {}, 0.0, 0.0
    for q, g in req.groupby("queue"):
        met = tot = 0
        for r in g.itertuples(index=False):
            if not counted(q, r):
                if operating:   # outside operating hours: still part of the understaffing sum
                    scheduled = gross[q][r.interval_start_utc] - on_break[q][r.interval_start_utc]
                    under += max(0, r.required - scheduled) * h
                    over += max(0, scheduled - r.required) * h
                continue''')
s=s.replace('''    hours = float(((sched["segment_end_utc"] - sched["segment_start_utc"]).dt.total_seconds() / 3600).sum())
    return {''','''    hours = float(((sched["segment_end_utc"] - sched["segment_start_utc"]).dt.total_seconds() / 3600).sum())
    extra = {}
    if cfg.get("max_hours_ratio"):
        req_hours = float(req["required"].sum()) * h
        extra = {"required_hours": round(req_hours, 1),
                 "hours_ratio": round(hours / req_hours, 4) if req_hours else None,
                 "max_hours_ratio": cfg["max_hours_ratio"],
                 "within_hours_ratio": bool(req_hours) and hours <= cfg["max_hours_ratio"] * req_hours + 1e-9}
    return {''')
s=s.replace('''        "agents_scheduled": int(sched["agent_id"].nunique()),
        "violations": {**audit(sched, cfg, agents), "min_cover": floor_gaps(gross, cross, grid, cfg)},
    }''','''        "agents_scheduled": int(sched["agent_id"].nunique()),
        **extra,
        "violations": {**audit(sched, cfg, agents), "min_cover": floor_gaps(gross, cross, grid, cfg),
                       **contract_audit(sched, req, cfg, agents, gross)},
    }''')
s+='''

def contract_audit(sched: pd.DataFrame, req: pd.DataFrame, cfg: dict, agents: list[Agent], gross: dict) -> dict[str, int]:
    """Rules some contracts add (Northwind SOW 2.1-2.3), audited only when the client config sets them:
    `min_rest_hours`, `split_shift_contracts`, `break.placement: max_surplus`. Counts shifts (an agent's
    segments on one local day) that break each rule."""
    rest_h = cfg.get("min_rest_hours")
    splits = cfg.get("split_shift_contracts")
    rule = cfg["break"]
    by_surplus = rule.get("placement") == "max_surplus"
    if not (rest_h or splits is not None or by_surplus):
        return {}
    z = ZoneInfo(cfg["tz"])
    contract = {a.agent_id: a.contract for a in agents}
    required = {(r.queue, r.interval_start_utc): r.required for r in req.itertuples(index=False)}
    grid = sorted(set(req["interval_start_utc"]))
    lo, hi = rule["window_hours"]
    length = timedelta(minutes=rule["minutes"])
    v = {}
    if rest_h:
        v["rest"] = 0
    if splits is not None:
        v["split_shift"] = 0
    if by_surplus:
        v["breaks"] = 0
    sched = sched.assign(day=[t.astimezone(z).date() for t in sched["segment_start_utc"]])
    for aid, g in sched.groupby("agent_id"):
        shifts = []
        for _, s in g.sort_values("segment_start_utc").groupby("day"):
            shifts.append(s)
        for prev, nxt in zip(shifts, shifts[1:]):
            if rest_h and nxt["segment_start_utc"].min() - prev["segment_end_utc"].max() < timedelta(hours=rest_h):
                v["rest"] += 1
        for s in shifts:
            segs = list(zip(s["segment_start_utc"], s["segment_end_utc"]))
            if splits is not None and len(segs) > 1 and contract.get(aid) not in splits:
                v["split_shift"] += 1
            if not by_surplus:
                continue
            hours = sum((e - b).total_seconds() for b, e in segs) / 3600
            brk = [(b, m) for b, m in zip(s["break_start_utc"], s["break_minutes"]) if m]
            if hours < rule["min_shift_hours"] - 1e-9:
                v["breaks"] += bool(brk)
                continue
            if len(brk) != 1 or brk[0][1] != rule["minutes"]:
                v["breaks"] += 1
                continue
            start, b, q = segs[0][0], brk[0][0], s["queue"].iloc[0]
            cands = [t for t in grid if start + timedelta(hours=lo) <= t <= start + timedelta(hours=hi)
                     and any(x <= t and t + length <= y for x, y in segs)]
            surplus = {t: gross[q][t] - required.get((q, t), 0) for t in cands}
            if b not in surplus or surplus[b] < max(surplus.values()):
                v["breaks"] += 1
    return v
'''
open(p,"w").write(s)
EOF
